query AnalyzeTableRelationshipsWithParams($tableId: ID!, $depth: Int, $includeStats: Boolean) {
  analyzeTableRelationships(tableId: $tableId, maxDepth: $depth, includeStatistics: $includeStats) {
    sourceTable {
      id
      identifier
      nodeCount
    }
    relationships {
      targetTable {
        id
        identifier
        nodeCount
      }
      relationshipType
      strength
      connectionCount
      bidirectional
    }
    statistics {
      totalRelationships
      strongRelationships
      weakRelationships
      averageStrength
      networkDensity
    }
    analysis {
      centralityScore
      clusteringCoefficient
      recommendations
    }
  }
}
